for (const scheme of ['light', 'dark']) {
  const p = await b.newPage({ viewport: { width: 1440, height: 900 }, colorScheme: scheme });
  await p.goto(base + '/'); await p.waitForLoadState('networkidle');
  const send = p.getByRole('button', { name: /send/i });
  results.push(`${scheme}: send disabled when empty = ${await send.isDisabled()}`);
  await p.screenshot({ path: `${out}/landing-${scheme}.png` });
  const box = p.getByRole('textbox').first();
  await box.click(); await box.type('Make the header blue'); await p.keyboard.down('Shift'); await p.keyboard.press('Enter'); await p.keyboard.up('Shift'); await box.type('and bold & 50% bigger?');
  await p.keyboard.press('Enter');
  await p.waitForURL(/\/workspace/); await p.waitForLoadState('networkidle'); await p.waitForTimeout(800);
  const u = new URL(p.url());
  results.push(`${scheme}: url prompt=${JSON.stringify(u.searchParams.get('prompt'))} model=${u.searchParams.get('model')}`);
  results.push(`${scheme}: message shown = ${await p.getByText('and bold & 50% bigger?').first().isVisible()}`);
  await p.screenshot({ path: `${out}/workspace-${scheme}.png` });
  await p.close();
}
const n = await b.newPage({ viewport: { width: 400, height: 800 } });
await n.goto(base + '/workspace?prompt=Make%20the%20nav%20sticky&model=gpt-5'); await n.waitForLoadState('networkidle');
results.push(`400px: horizontal scroll = ${await n.evaluate(() => document.documentElement.scrollWidth > innerWidth)}`);
await n.screenshot({ path: `${out}/workspace-400.png` });
await b.close();
console.log(results.join('\n'));
EOF
node run.mjs $S/shots 2>&1 | tail -15

