mkdir -p apps/web/.scratch && cat > apps/web/.scratch/hero.mjs <<'EOF'
const base = 'http://localhost:3300';
const redact = s => String(s).replace(/sk-[A-Za-z0-9_-]{8,}/g, '[REDACTED]');
const t0 = Date.now();
const sbRes = await fetch(`${base}/api/sandbox`, {method: 'POST', body: JSON.stringify({sandboxId: null})});
if (!sbRes.ok) { console.log('sandbox', sbRes.status, redact(await sbRes.text())); process.exit(1); }
const {sandboxId, previewUrl} = await sbRes.json();
console.log(JSON.stringify({step: 'sandbox', sandboxId, previewUrl, s: Math.round((Date.now() - t0) / 1000)}));
const messages = [];
async function turn(text) {
  messages.push({id: `u${messages.length}`, role: 'user', parts: [{type: 'text', text}]});
  const t = Date.now();
  const res = await fetch(`${base}/api/chat`, {method: 'POST', body: JSON.stringify({
    messages, model: 'claude-sonnet-5-5', sandboxId,
    credential: {provider: 'anthropic', kind: 'api-key', apiKey: process.env.ANTHROPIC_EVAL_API_KEY},
  })});
  if (!res.ok) { console.log('chat', res.status, redact(await res.text())); process.exit(1); }
  const out = {text, tools: [], meta: {}, verify: null, files: null, checkpoint: null, errors: [], assistant: {id: `a${messages.length}`, role: 'assistant', parts: []}};
  const reader = res.body.getReader(); const dec = new TextDecoder(); let buf = '';
  for (;;) {
    const {done, value} = await reader.read(); if (done) break;
    buf += dec.decode(value, {stream: true});
    let i; while ((i = buf.indexOf('\n\n')) >= 0) {
      const chunk = buf.slice(0, i); buf = buf.slice(i + 2);
      const line = chunk.split('\n').find(l => l.startsWith('data: ')); if (!line || line === 'data: [DONE]') continue;
      const p = JSON.parse(line.slice(6));
      if (p.messageMetadata) Object.assign(out.meta, p.messageMetadata);
      if (p.type === 'tool-input-available') out.tools.push(p.toolName);
      if (p.type === 'data-verify') out.verify = p.data.checks?.map(c => `${c.name}:${c.status}`).join(' ');
      if (p.type === 'data-diff') out.files = p.data.filesTouched;
      if (p.type === 'data-checkpoint') out.checkpoint = p.data.id;
      if (p.type === 'error') out.errors.push(redact(p.errorText));
      if (p.type === 'text-delta') { const last = out.assistant.parts.at(-1); last?.type === 'text' ? (last.text += p.delta) : out.assistant.parts.push({type: 'text', text: p.delta}); }
    }
  }
  messages.push(out.assistant);
  const {assistant, ...rest} = out;
  console.log(JSON.stringify({...rest, s: Math.round((Date.now() - t) / 1000)}));
}
await turn('Make the hero heading blue');
await turn('Now make the hero heading bold too');
EOF
cd apps/web; for i in $(seq 1 30); do curl -s -o /dev/null -w '%{http_code}' http://localhost:3300/ | grep -q 200 && break; sleep 2; done; echo ready

