cat > .scratch/lf.mjs <<'EOF'
const auth = 'Basic ' + Buffer.from(`${process.env.LANGFUSE_PUBLIC_KEY}:${process.env.LANGFUSE_SECRET_KEY}`).toString('base64');
for (const id of process.argv.slice(2)) {
  const r = await fetch(`${process.env.LANGFUSE_BASE_URL}/api/public/traces/${id}`, {headers: {Authorization: auth}});
  if (!r.ok) { console.log(id, 'HTTP', r.status); continue; }
  const t = await r.json();
  const gens = (t.observations ?? []).filter(o => o.type === 'GENERATION').sort((a, b) => a.startTime.localeCompare(b.startTime));
  const steps = gens.map(g => ({in: g.usageDetails?.input ?? g.usage?.input, out: g.usageDetails?.output ?? g.usage?.output, cacheRead: g.usageDetails?.input_cache_read ?? g.usageDetails?.cache_read_input_tokens ?? g.usageDetails?.cacheReadInputTokens ?? null, keys: Object.keys(g.usageDetails ?? {}).join(',')}));
  const sbx = JSON.stringify(t.metadata ?? {}).match(/"sandbox[^}]*}/)?.[0] ?? null;
  console.log(JSON.stringify({trace: id, observations: t.observations?.length, generations: steps, sandbox: sbx, cost: t.totalCost}));
}
EOF
