cat > .scratch/lf3.mjs <<'EOF'
const auth = 'Basic ' + Buffer.from(`${process.env.LANGFUSE_PUBLIC_KEY}:${process.env.LANGFUSE_SECRET_KEY}`).toString('base64');
const from = new Date(Date.now() - 60 * 60e3).toISOString(), to = new Date().toISOString();
const r = await fetch(`${process.env.LANGFUSE_BASE_URL}/api/public/v2/observations?fields=core,basic,usage,metadata&fromStartTime=${from}&toStartTime=${to}&limit=200`, {headers: {Authorization: auth}});
const txt = await r.text();
if (!r.ok) { console.log(r.status, txt.slice(0, 400)); process.exit(); }
const body = JSON.parse(txt); const rows = body.data ?? body;
const want = new Set(process.argv.slice(2));
for (const id of want) {
  const mine = rows.filter(o => o.traceId === id);
  const gens = mine.filter(o => (o.type ?? '').toUpperCase() === 'GENERATION').sort((a, b) => String(a.startTime).localeCompare(String(b.startTime)));
