--- tls/client
import {resolve} from 'node:path';

export function verifiedDatabaseUrl(name: 'DATABASE_URL' | 'DIRECT_URL') {
  const connectionString = process.env[name];
  if (!connectionString) return;

  const url = URL.parse(connectionString);
  if (!url) throw new Error(`${name} must be a valid URL.`);

  url.searchParams.set('sslmode', 'verify-full');
  url.searchParams.set('sslrootcert', resolve('supabase-ca.crt'));
  return url.href;
}
import 'server-only';
import {drizzle, type PostgresJsDatabase} from 'drizzle-orm/postgres-js';
import postgres from 'postgres';
import * as schema from './schema';
import {verifiedDatabaseUrl} from './tls';

const globalDb = globalThis as typeof globalThis & {betterlookDb?: PostgresJsDatabase<typeof schema>};
let db: PostgresJsDatabase<typeof schema> | undefined;

export function getDb() {
  const cached = db ?? globalDb.betterlookDb;
  if (cached) return cached;

  const url = verifiedDatabaseUrl('DATABASE_URL');
  if (!url) throw new Error('DATABASE_URL is required.');

  db = drizzle(postgres(url, {prepare: false}), {schema});
  if (process.env.NODE_ENV === 'development') globalDb.betterlookDb = db;
  return db;
}
import {defineConfig} from 'drizzle-kit';
import {verifiedDatabaseUrl} from './src/lib/db/tls';

const url = verifiedDatabaseUrl('DIRECT_URL');

export default defineConfig({
  dialect: 'postgresql',
  schema: './src/lib/db/schema.ts',
  out: '../../supabase/migrations',
  schemaFilter: ['public'],
  entities: {roles: {provider: 'supabase'}},
  dbCredentials: url ? {url} : undefined,
});
