let rows = [], cursor;
for (let i = 0; i < 10; i++) {
  const u = `${process.env.LANGFUSE_BASE_URL}/api/public/v2/observations?fields=core,basic,usage,metadata&fromStartTime=${from}&toStartTime=${to}&limit=200${cursor ? '&cursor=' + cursor : ''}`;
  const b = await (await fetch(u, {headers: {Authorization: auth}})).json();
  rows.push(...(b.data ?? [])); cursor = b.meta?.cursor ?? b.meta?.nextCursor; if (!cursor) break;
}
const mine = rows.filter(o => o.traceId === id).sort((a, b) => String(a.startTime).localeCompare(String(b.startTime)));
for (const o of mine) {
  const m = o.metadata ?? {}; const attrs = m.attributes ?? m;
  const pick = k => Object.entries(attrs).filter(([key]) => key.includes(k)).map(([key, v]) => `${key.split('.').slice(-2).join('.')}=${String(v).slice(0, 60)}`);
  console.log([String(o.startTime).slice(11, 23), String(o.endTime ?? '').slice(11, 23), o.type, o.name, o.level !== 'DEFAULT' ? o.level : '', (o.statusMessage ?? '').slice(0, 120),
    o.usageDetails ? JSON.stringify(o.usageDetails) : '', ...pick('finish'), ...pick('maxOutput'), ...pick('max_tokens'), ...pick('toolCall.name')].filter(Boolean).join(' | '));
}
console.log('rows', mine.length);
