const base = 'http://localhost:3300';
const redact = s => String(s).replace(/sk-[A-Za-z0-9_-]{8,}/g, '[REDACTED]');
const t0 = Date.now();
const sbRes = await fetch(`${base}/api/sandbox`, {method: 'POST', body: JSON.stringify({sandboxId: null})});
if (!sbRes.ok) { console.log('sandbox', sbRes.status, redact(await sbRes.text())); process.exit(1); }
const {sandboxId, previewUrl} = await sbRes.json();
console.log(JSON.stringify({step: 'sandbox', sandboxId, previewUrl, s: Math.round((Date.now() - t0) / 1000)}));

const text = 'Design a landing page for addidas';
const messages = [{id: 'u0', role: 'user', parts: [{type: 'text', text}]}];
const t = Date.now();
const res = await fetch(`${base}/api/chat`, {method: 'POST', body: JSON.stringify({
  messages, model: 'claude-sonnet-5-5', sandboxId,
  credential: {provider: 'anthropic', kind: 'api-key', apiKey: process.env.ANTHROPIC_EVAL_API_KEY},
})});
if (!res.ok) { console.log('chat', res.status, redact(await res.text())); process.exit(1); }
const calls = new Map();
const meta = {}; let verify = null, diff = null, checkpoint = null; const errors = []; let reasoningChars = 0, reasoningParts = 0; let finalText = '';
const reader = res.body.getReader(); const dec = new TextDecoder(); let buf = '';
for (;;) {
  const {done, value} = await reader.read(); if (done) break;
  buf += dec.decode(value, {stream: true});
  let i; while ((i = buf.indexOf('\n\n')) >= 0) {
    const chunk = buf.slice(0, i); buf = buf.slice(i + 2);
    const line = chunk.split('\n').find(l => l.startsWith('data: ')); if (!line || line === 'data: [DONE]') continue;
    const p = JSON.parse(line.slice(6));
    if (p.messageMetadata) Object.assign(meta, p.messageMetadata);
    if (p.toolCallId) {
      const c = calls.get(p.toolCallId) ?? {tool: p.toolName, path: undefined, state: 'input-streaming', note: undefined};
      if (p.toolName) c.tool = p.toolName;
      if (p.type === 'tool-input-available') { c.state = 'input-available'; c.path = p.input?.path; }
      if (p.type === 'tool-output-available' && !p.preliminary) c.state = 'output-available';
      if (p.type === 'tool-output-error' || p.type === 'tool-input-error') { c.state = p.type === 'tool-input-error' ? 'input-error' : 'output-error'; c.note = redact(p.errorText).slice(0, 70); }
      if (p.type === 'tool-output-denied') c.state = 'output-denied';
      if (p.type === 'tool-approval-request') c.state = 'approval-requested';
      calls.set(p.toolCallId, c);
    }
    if (p.type === 'reasoning-start') reasoningParts++;
    if (p.type === 'reasoning-delta') reasoningChars += p.delta.length;
    if (p.type === 'text-delta') finalText += p.delta;
    if (p.type === 'data-verify') verify = p.data;
    if (p.type === 'data-diff') diff = {filesTouched: p.data.filesTouched, bytes: p.data.diff.length};
    if (p.type === 'data-checkpoint') checkpoint = p.data.id;
    if (p.type === 'error') errors.push(redact(p.errorText));
  }
}
console.log(JSON.stringify({step: 'turn', s: Math.round((Date.now() - t) / 1000), meta, checkpoint, diff, errors, reasoningParts, reasoningChars, finalTextTail: finalText.slice(-300)}));
console.log(JSON.stringify({step: 'verify', ok: verify?.ok, checks: verify?.checks?.map(c => `${c.name}:${c.status}`)}));
for (const [id, c] of calls) console.log(JSON.stringify({step: 'tool', id: id.slice(-8), ...c}));
const unresolved = [...calls.values()].filter(c => !['output-available', 'output-error', 'input-error', 'output-denied'].includes(c.state));
console.log(JSON.stringify({step: 'summary', calls: calls.size, unresolved: unresolved.length}));

