git merge --no-ff bb8a4749 -m "Merge branch 'evals-baseline' (Haiku first 20 trials) into betterlook" 2>&1 | tail -1 && bun install 2>&1 | tail -1 && cd apps/web && for i in 1 2; do echo "== run $i"; bun run typecheck 2>&1 | tail -1; bun test 2>&1 | grep -E "^ *[0-9]+ (pass|fail)"; done; bun run build 2>&1 | grep -E "Compiled|rror" | head -3; node -e '
const fs=require("fs");const env=Object.fromEntries(fs.readFileSync(".env","utf8").split("\n").filter(l=>l.includes("=")&&!l.startsWith("#")).map(l=>[l.slice(0,l.indexOf("=")),l.slice(l.indexOf("=")+1).replace(/^"|"$/g,"")]));
const {execSync}=require("child_process");const diff=execSync("git diff origin/main betterlook",{maxBuffer:1<<28}).toString();
let hits=0;for(const [k,v] of Object.entries(env)){if(v.length>=8&&!/^https?:\/\//.test(v)&&diff.includes(v)){hits++;console.log("LEAK of value for",k);}}
const added=diff.split("\n").filter(l=>l.startsWith("+")).join("\n");
const pat=/sk-ant-[A-Za-z0-9_-]{10,}|sk-lf-[0-9a-f-]{20,}|pk-lf-[0-9a-f-]{20,}|eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}|postgres(ql)?:\/\/[^:<\s]+:[^@<\s]{6,}@|BEGIN (RSA |EC )?PRIVATE KEY|@secndai|gmail\.com/g;
const files=execSync("git diff --name-only origin/main betterlook").toString().split("\n").filter(Boolean);
console.log("env value hits:",hits,"| pattern hits:",(added.match(pat)||[]).length,"| env files:",files.filter(f=>/(^|\/)\.env(\.|$)/.test(f)&&!f.endsWith(".example")).length,"| scratch files:",files.filter(f=>f.includes(".scratch/")).length);'

